  /// The parameter names for these three parameters are `a`, `b`, and `see`,
  /// respectively.
  @_spi(Testing // c
)
  public var parameterName: TokenSyntax? {
    // If there were two names, the second is the parameter name.
    if let secondName {
      if secondName.text == "_" {
        return nil
